//! Cases in the IDL-to-Rust route found beside GitHub #62, #63 and #64, and
//! the enum-prefix switch and the naming scheme of GitHub #61 (`idl/`,
//! generated by `build.rs`).
//!
//! That the crate compiles is the first half of each check: every case
//! here stopped the generator or rustc before. `cargo run` checks the rest:
//! the key-only read gives the key in XCDR2 and XCDR1, little and big
//! endian; the `@default` values are the declared ones; the enumerators
//! carry the cut names in Rust and the IDL names in a content filter; under
//! the Rust naming scheme the names pass `nonstandard_style`, and the type
//! name and the filter's field names are still the IDL's.

use zerodds_dcps::DdsType;
use zerodds_float128::Float128;

#[allow(
    dead_code,
    missing_docs,
    non_camel_case_types,
    non_snake_case,
    unused_imports
)]
mod names {
    include!(concat!(env!("OUT_DIR"), "/names.rs"));
}

#[allow(
    dead_code,
    missing_docs,
    non_camel_case_types,
    non_snake_case,
    unused_imports
)]
mod dropped {
    include!(concat!(env!("OUT_DIR"), "/dropped.rs"));
}

#[allow(
    dead_code,
    missing_docs,
    non_camel_case_types,
    non_snake_case,
    unused_imports
)]
mod defaults {
    include!(concat!(env!("OUT_DIR"), "/defaults.rs"));
}

#[allow(
    dead_code,
    missing_docs,
    non_camel_case_types,
    non_snake_case,
    unused_imports
)]
mod enum_prefix {
    include!(concat!(env!("OUT_DIR"), "/enum_prefix.rs"));
}

/// Generated with `rust_naming(RustNaming::Rust)`: the lints on names are
/// errors here.
#[deny(nonstandard_style)]
#[allow(dead_code, missing_docs, unused_imports)]
mod rust_naming {
    include!(concat!(env!("OUT_DIR"), "/rust_naming.rs"));
}

/// The four encodings: XCDR2 and XCDR1, each little and big endian.
const MODES: [(&str, bool, bool); 4] = [
    ("XCDR2 LE", false, false),
    ("XCDR2 BE", false, true),
    ("XCDR1 LE", true, false),
    ("XCDR1 BE", true, true),
];

fn write<T: DdsType>(value: &T, xcdr1: bool, big_endian: bool) -> Vec<u8> {
    let mut out = Vec::new();
    match (xcdr1, big_endian) {
        (false, false) => T::encode(value, &mut out),
        (false, true) => T::encode_be(value, &mut out),
        (true, false) => T::encode_xcdr1(value, &mut out),
        (true, true) => T::encode_xcdr1_be(value, &mut out),
    }
    .expect("the sample encodes");
    out
}

fn keys<T: DdsType>(bytes: &[u8], xcdr1: bool, big_endian: bool) -> T {
    T::decode_key_members(bytes, xcdr1, big_endian)
        .expect("a generated type has a key-only read")
        .expect("the key-only read succeeds")
}

/// Members named like the codec's locals, keywords with no raw form,
/// modules `std` and `core`, types named like what the codec writes.
fn own_names() {
    let locals = names::Locals {
        r: 1,
        value: 2,
        zd_origin: 3,
        w: 4,
        pid: 5,
        end: 6,
        r#gen: 7,
        id: 8,
    };
    for (mode, xcdr1, big_endian) in MODES {
        let key: names::Locals = keys(&write(&locals, xcdr1, big_endian), xcdr1, big_endian);
        assert_eq!(key.id, 8, "{mode}: the key-only read");
        assert_eq!(key.r, 0, "{mode}: a member it steps over is at its default");
    }
    let mut own = names::crate_::Self_::default();
    own.super_ = 9;
    assert_eq!(own.super_, 9, "the member `super` is the field `super_`");
    let _ = (
        names::std::S::default(),
        names::core::T::default(),
        names::Option_::default(),
        names::Vec_::default(),
        names::Reader_::default(),
    );
    println!(
        "names: members r, value, zd_origin, w, pid, end, gen; module crate, struct Self, \
         member super; modules std and core; types Option, Vec, Reader — all compile, \
         the key-only read gives id 8 in 4 encodings"
    );
}

/// An array dropped by the key-only read inside a sequence, a map, a box.
fn dropped_arrays() {
    let mut sample = dropped::Dropped::default();
    sample.seqs = vec![['a', 'b', 'c', 'd']];
    sample.c = Box::new(['w', 'x', 'y', 'z']);
    sample.id = 42;
    for (mode, xcdr1, big_endian) in MODES {
        let key: dropped::Dropped = keys(&write(&sample, xcdr1, big_endian), xcdr1, big_endian);
        assert_eq!(key.id, 42, "{mode}: the key-only read");
        assert!(key.seqs.is_empty(), "{mode}: seqs is stepped over");
        assert_eq!(
            DdsType::key_hash(&key),
            DdsType::key_hash(&sample),
            "{mode}: the KeyHash"
        );
    }
    println!(
        "dropped: sequence<C4>, map<long, C4>, @external char[4], long double[2] beside the key \
         compile; the key-only read gives id 42 in 4 encodings"
    );
}

/// Numeric `@default` values in the member's type.
fn numeric_defaults() {
    let sample = defaults::Defaults::default();
    assert_eq!(sample.f, 2.5_f32, "@default(CF)");
    assert_eq!(sample.fx, "1.00", "@default(1) on fixed<5,2>");
    assert_eq!(
        sample.one,
        Float128::from_f64(1.0),
        "@default(1) on long double"
    );
    assert_eq!(
        sample.half,
        Float128::from_f64(1.5),
        "@default(1.5) on long double"
    );
    println!(
        "defaults: @default(CF) float {}, @default(1) fixed<5,2> \"{}\", \
         @default(1) and @default(1.5) long double 1 and 1.5",
        sample.f, sample.fx
    );
}

/// GitHub #61: the enumerators without their enumeration's name.
fn enum_prefix_switch() {
    use enum_prefix::{Choice, MyEnum};
    let sample = Choice::default();
    assert_eq!(sample.chosen, MyEnum::B, "@default(MY_ENUM_B)");
    assert_eq!(sample.first, MyEnum::A, "the first literal");
    let mut written = Choice::default();
    written.id = 3;
    written.chosen = MyEnum::MY_ENUM_1;
    for (mode, xcdr1, big_endian) in MODES {
        let key: Choice = keys(&write(&written, xcdr1, big_endian), xcdr1, big_endian);
        assert_eq!(key.id, 3, "{mode}: the key-only read");
    }
    let filtered = format!("{:?}", DdsType::field_value(&written, "chosen"));
    assert!(
        filtered.contains("MY_ENUM_1"),
        "a content filter reads the IDL name: {filtered}"
    );
    println!(
        "#61 strip_enum_prefix(true): MY_ENUM_A is MyEnum::A, MY_ENUM_B is MyEnum::B, \
         MY_ENUM_1 keeps its prefix; a content filter reads {filtered}"
    );
}

/// GitHub #61: the names after RFC 430, and the IDL names where the wire
/// and a content filter read them.
fn rust_naming_scheme() {
    use rust_naming::sensor_data::{
        FLAG_ERROR, FLAG_READY, HttpReading, MAX_SAMPLES, ReadingKind, ReadingValue,
    };
    assert_eq!(MAX_SAMPLES, 8);
    let mut reading = HttpReading::default();
    assert_eq!(reading.kind, ReadingKind::Filtered, "@default(READING_KIND_filtered)");
    reading.sensor_id = 7;
    reading.kind = ReadingKind::Raw;
    reading.samples = vec![1, 2, 3];
    reading.last_value = ReadingValue::FilteredValue(2.5);
    reading.flags = FLAG_READY | FLAG_ERROR;
    for (mode, xcdr1, big_endian) in MODES {
        let bytes = write(&reading, xcdr1, big_endian);
        let key: HttpReading = keys(&bytes, xcdr1, big_endian);
        assert_eq!(key.sensor_id, 7, "{mode}: the key-only read");
    }
    let mut bytes = Vec::new();
    DdsType::encode(&reading, &mut bytes).expect("encode");
    let back = <HttpReading as DdsType>::decode(&bytes).expect("decode");
    assert_eq!(back, reading);
    // The registered type name and the filter's field names are the IDL's.
    assert_eq!(<HttpReading as DdsType>::TYPE_NAME, "Sensor_Data::HTTPReading");
    assert!(DdsType::field_value(&reading, "sensorId").is_some());
    assert!(DdsType::field_value(&reading, "sensor_id").is_none());
    println!(
        "#61 rust_naming(RustNaming::Rust): Sensor_Data::HTTPReading is \
         sensor_data::HttpReading with the field sensor_id, registered as {}",
        <HttpReading as DdsType>::TYPE_NAME
    );
}

fn main() {
    own_names();
    dropped_arrays();
    numeric_defaults();
    enum_prefix_switch();
    rust_naming_scheme();
    println!("the IDL-to-Rust cases hold");
}
